//! Own native admission backed by one existing parent reservation. Data is not
//! a permit: Authority checks the canonical binding again before every effect.
use super::{model,received_request::Source,delegation::Allowance,admission::AdmissionSpec};
use serde::{Serialize,Deserialize};
#[derive(Clone,Debug,PartialEq,Eq,Serialize,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct Funding{pub schema_version:u32,pub source:Source,pub allowance:Allowance,pub own_origin_hash:String,#[serde(default,skip_serializing_if="Vec::is_empty")]pub previous:Vec<super::continuation::Anchor>}
impl Funding{
 pub(super)fn from_goal(g:&model::Record)->model::Result<Option<Self>>{let Some(o)=&g.spec.received_from else{return Ok(None);};let Some(d)=&o.body.delegation else{return Ok(None);};if !o.valid_for(&g.spec){return Err(model::Error::Conflict);}Ok(Some(Self{schema_version:if o.body.schema_version==4{6}else{1},source:o.body.source.clone(),allowance:d.allowance.clone(),own_origin_hash:model::fingerprint(o)?,previous:vec![]}))}
 pub(super)fn basic(&self)->bool{let mut ids=std::collections::BTreeSet::new();self.source.valid()&&self.allowance.valid()&&super::authority::decode(&self.own_origin_hash).is_some()&&match self.schema_version{1|5|6|7|9=>self.previous.is_empty(),2|3|8=>(if self.schema_version==8{self.previous.len()==1}else{(1..32).contains(&self.previous.len())})&&self.previous.iter().all(|a|a.native_schema.is_none()&&model::token(&a.decision_id)&&ids.insert(&a.decision_id)&&[&a.spec_hash,&a.row_hash,&a.grant_hash].iter().all(|h|super::authority::decode(h).is_some())&&a.budget.valid(a.budget.deadline_at.saturating_sub(1))&&!a.resolved_model.is_empty()),4=>(1..32).contains(&self.previous.len())&&self.previous.iter().all(|a|matches!(a.native_schema,Some(11|16))&&model::token(&a.decision_id)&&ids.insert(&a.decision_id)&&[&a.spec_hash,&a.row_hash,&a.grant_hash].iter().all(|h|super::authority::decode(h).is_some())&&(if a.native_schema==Some(16){a.budget.valid_runtime_continuation(a.budget.deadline_at.saturating_sub(1))}else{a.budget.valid_runtime(a.budget.deadline_at.saturating_sub(1))})&&a.resolved_model.is_empty()),_=>false}}
 pub(super)fn valid_for(&self,s:&AdmissionSpec)->bool{
  let continuation=match(self.schema_version,&s.continuation){(1,None)=>true,(9,None)=>s.peer_funded_iteration(),(5,None)=>s.schema_version==17,(6,None)=>s.schema_version==18,(7,None)=>s.schema_version==19,(2|3|4|8,Some(c))=>s.schema_version==(if self.schema_version==8{20}else if self.schema_version==4{16}else if self.schema_version==3{14}else{13})&&c.schema_version==(if self.schema_version==8{10}else if self.schema_version==4{8}else if self.schema_version==3{7}else{6})&&c.basic()&&c.previous==self.previous&&c.charge.model_calls.checked_add(s.budget.max_model_calls.into()).is_some_and(|n|n<=u64::from(self.allowance.model_calls))&&c.charge.tool_calls.checked_add(s.budget.max_tool_calls.into()).is_some_and(|n|n<=u64::from(self.allowance.tool_calls))&&c.charge.output_bytes.checked_add(s.budget.max_output_bytes).is_some_and(|n|n<=self.allowance.output_bytes),_=>false};
  self.basic()&&continuation&&s.owner.pet_id==self.source.recipient_pet_id&&s.goal_id!=self.source.sender_goal_id&&s.approved_at>=self.source.received_at&&s.budget.deadline_at<=self.source.deadline_at&&s.budget.max_model_calls<=self.allowance.model_calls&&s.budget.max_tool_calls<=self.allowance.tool_calls&&s.budget.max_output_bytes<=self.allowance.output_bytes
 }
 pub(super)fn matches(&self,g:&model::Record)->bool{let mut base=self.clone();base.schema_version=if g.spec.received_from.as_ref().is_some_and(|o|o.body.schema_version==4){6}else{1};base.previous.clear();Self::from_goal(g).ok().flatten().as_ref()==Some(&base)}
}
#[derive(Clone,Debug,PartialEq,Eq,Serialize,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct ChildBinding{pub goal_id:String,pub pet_id:String,pub decision_id:String,pub admission_hash:String,pub bound_at:u64}
impl ChildBinding{
 pub(super)fn capture(s:&AdmissionSpec,now:u64)->model::Result<Self>{Ok(Self{goal_id:s.goal_id.clone(),pet_id:s.owner.pet_id.clone(),decision_id:s.decision_id.clone(),admission_hash:model::fingerprint(s)?,bound_at:now})}
 pub(super)fn matches(&self,s:&AdmissionSpec)->bool{self.goal_id==s.goal_id&&self.pet_id==s.owner.pet_id&&self.decision_id==s.decision_id&&model::fingerprint(s).ok().as_ref()==Some(&self.admission_hash)}
 pub(super)fn valid(&self,r:&super::delegation::Reservation,b:&super::authority::Grant)->bool{model::goal_id(&self.goal_id)&&self.goal_id!=b.goal_id&&self.pet_id==r.recipient_pet_id&&model::token(&self.decision_id)&&self.decision_id!=b.decision_id&&super::authority::decode(&self.admission_hash).is_some()&&self.bound_at>=r.reserved_at&&self.bound_at<=b.updated_at}
}
